def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return min(budget, 18.0)

    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    pressure = 0.0

    for oid, opp in alive:
        obudget = float(opp.get('budget', 0))
        ohp = float(opp.get('hp', 0))
        onwd = int(opp.get('no_water_days', 0))
        if obudget >= DAILY_SALARY * 6:
            rich_opp += 1
        if ohp <= 3 or onwd >= 2:
            urgent_opp += 1

        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            b = float(bid)
            prev_bids.append(b)
            pressure = max(pressure, b)

    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    high_prev = max(prev_bids) if prev_bids else 0.0

    supply_ratio = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_ratio < 0:
        supply_ratio = 0.0
    if supply_ratio > 1:
        supply_ratio = 1.0

    critical = hp <= 2 or no_water_days >= 2
    strained = hp <= 4 or no_water_days >= 1

    if critical:
        bid = max(92.0, high_prev + 4.0, DAILY_SALARY * (1.18 + 0.12 * supply_ratio))
        return min(budget, bid)

    if strained:
        if high_prev >= 120:
            bid = 34.0 + 10.0 * supply_ratio
        else:
            bid = max(58.0 + 12.0 * supply_ratio, avg_prev + 2.5)
        return min(budget, bid)

    if high_prev >= 135:
        bid = 18.0 + 8.0 * supply_ratio
    elif high_prev >= 100:
        bid = 24.0 + 10.0 * supply_ratio
    else:
        bid = max(36.0 + 12.0 * supply_ratio, avg_prev + 1.5)

    if urgent_opp >= 2:
        bid -= 6.0
    if rich_opp >= 2 and high_prev < 100:
        bid += 6.0
    if day >= 8 and hp >= 6 and no_water_days == 0:
        bid -= 4.0

    if bid < 0:
        bid = 0.0
    return min(budget, bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 60.0

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    bid = min(my_status['budget'], avg_prev * 1.05)
    return max(bid, 45.0)
